"""Export the first diagram SVG in an HTML file to SVG and/or PNG."""

from __future__ import annotations

import argparse
import re
import sys
from pathlib import Path


FONT_IMPORT = (
    "@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700"
    "&amp;family=Geist+Mono:wght@400;500;600&amp;display=swap');"
    "@font-face{font-family:'Duyet Serif';font-style:normal;font-weight:400;"
    "src:url('data:font/woff2;base64,') format('woff2');}"
    "@font-face{font-family:'Duyet Serif';font-style:italic;font-weight:400;"
    "src:url('data:font/woff2;base64,') format('woff2');}"
)

PRESETS = {
    "social-portrait": (960, 1200),
    "square": (1080, 1080),
    "story": (1080, 1920),
    "landscape": (1200, 628),
    "video-landscape": (1920, 1080),
}


def extract_svg(html_path: Path) -> str:
    """Extract and validate the first SVG element from an HTML source."""
    source = html_path.read_text(encoding="utf-8")
    match = re.search(r"<svg\b[\s\S]*?</svg>", source, flags=re.IGNORECASE)
    if not match:
        raise ValueError(f"No <svg> block found in {html_path}")

    svg = match.group(0)
    opening = re.match(r"<svg\b[^>]*>", svg, flags=re.IGNORECASE)
    if opening is None:
        raise ValueError("Could not parse the SVG opening tag")
    opening_tag = opening.group(0)
    if not re.search(r"\bviewBox\s*=", opening_tag, flags=re.IGNORECASE):
        raise ValueError("SVG has no viewBox; refusing to guess export dimensions")
    if not re.search(r"\bxmlns\s*=", opening_tag, flags=re.IGNORECASE):
        opening_tag = opening_tag[:-1] + ' xmlns="http://www.w3.org/2000/svg">'
        svg = opening_tag + svg[opening.end():]

    style = f"<style>{FONT_IMPORT}</style>"
    if re.search(r"<defs\b", svg, flags=re.IGNORECASE):
        svg = re.sub(r"(<defs\b[^>]*>)", rf"\1{style}", svg, count=1, flags=re.IGNORECASE)
    else:
        svg = re.sub(r"(<svg\b[^>]*>)", rf"\1<defs>{style}</defs>", svg, count=1, flags=re.IGNORECASE)
    return '<?xml version="1.0" encoding="UTF-8"?>\n' + svg


def export_svg(source: Path, output: Path) -> Path:
    """Write a standalone SVG containing the diagram only."""
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(extract_svg(source), encoding="utf-8", newline="\n")
    return output


def export_png(
    source: Path,
    output: Path,
    scale: float = 2,
    full_page: bool = False,
    viewport: tuple[int, int] | None = None,
    html_class: str | None = None,
) -> Path:
    """Screenshot the SVG or the whole HTML page with Playwright."""
    try:
        from playwright.sync_api import sync_playwright
    except ImportError as exc:
        raise RuntimeError(
            "Playwright isn't installed. To enable PNG export, run:\n"
            "pip install playwright\n"
            "playwright install chromium\n"
            "Then ask me to export again."
        ) from exc

    output.parent.mkdir(parents=True, exist_ok=True)
    with sync_playwright() as playwright:
        browser = playwright.chromium.launch()
        page = browser.new_page(device_scale_factor=scale)
        if viewport is not None:
            page.set_viewport_size({"width": viewport[0], "height": viewport[1]})
        page.goto(source.resolve().as_uri(), wait_until="networkidle")
        if html_class:
            page.evaluate(
                "className => document.documentElement.classList.add(className)",
                html_class,
            )
        page.evaluate("document.fonts.ready")
        if full_page and viewport is None:
            page.screenshot(path=str(output), full_page=True)
        else:
            if full_page:
                page.screenshot(path=str(output), full_page=False)
            else:
                page.locator("svg").first.screenshot(path=str(output), omit_background=True)
        browser.close()
    return output


def _scale_label(scale: float) -> str:
    """Return a compact, filename-safe label for a scale value."""
    return f"{scale:g}".replace(".", "-")


def _safe_variant(value: str) -> str:
    """Normalize a user-provided filename variant without dropping Unicode letters."""
    value = re.sub(r"[^\w.-]+", "-", value.strip(), flags=re.UNICODE)
    value = value.strip("-._")
    if not value:
        raise ValueError("--variant must contain at least one filename-safe character")
    return value


def _output_stem(args: argparse.Namespace, source_stem: str) -> str:
    """Build a descriptive output stem from PNG capture options."""
    labels = ["full-page" if args.full_page else "diagram-only"]
    if args.preset:
        labels.append(f"preset-{args.preset}")
    elif args.width is not None:
        labels.append(f"viewport-{args.width}x{args.height}")
    if args.format in ("png", "both"):
        labels.append(f"scale-{_scale_label(args.scale)}")
    if args.variant:
        labels.append(_safe_variant(args.variant))
    return "__".join([source_stem, *labels])


def _unique_stem(output_dir: Path, stem: str, extensions: tuple[str, ...]) -> str:
    """Avoid replacing any requested output file by adding a numeric suffix."""
    candidate = stem
    counter = 2
    while any((output_dir / f"{candidate}.{extension}").exists() for extension in extensions):
        candidate = f"{stem}-{counter}"
        counter += 1
    return candidate


def _print_output(path: Path) -> None:
    """Print output paths as UTF-8 even when Windows console uses a legacy code page."""
    sys.stdout.buffer.write(f"{path}\n".encode("utf-8"))


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("source", type=Path, help="Generated diagram HTML file")
    parser.add_argument(
        "--format",
        choices=("svg", "png", "both"),
        default="png",
        help="Output format, default: png",
    )
    parser.add_argument("--scale", type=float, default=2, help="PNG device scale factor, default: 2")
    parser.add_argument("--output-dir", type=Path, help="Output directory; default: source directory")
    parser.add_argument("--full-page", action="store_true", help="PNG: capture the complete HTML page instead of SVG only")
    parser.add_argument(
        "--diagram-only",
        action="store_true",
        help="PNG: capture the diagram SVG only (default; mutually exclusive with --full-page)",
    )
    parser.add_argument("--preset", choices=tuple(PRESETS), help="PNG canvas preset; requires --full-page")
    parser.add_argument("--width", type=int, help="Custom PNG viewport width; use with --height and --full-page")
    parser.add_argument("--height", type=int, help="Custom PNG viewport height; use with --width and --full-page")
    parser.add_argument(
        "--variant",
        help="Extra filename label; use to distinguish otherwise identical exports",
    )
    args = parser.parse_args()

    source = args.source.resolve()
    if not source.is_file():
        parser.error(f"Source file not found: {source}")
    if args.scale <= 0 or args.scale > 4:
        parser.error("--scale must be greater than 0 and no more than 4")
    if args.full_page and args.diagram_only:
        parser.error("--diagram-only and --full-page cannot be used together")
    if args.variant:
        try:
            _safe_variant(args.variant)
        except ValueError as error:
            parser.error(str(error))
    if args.preset and not args.full_page:
        parser.error("--preset requires --full-page")
    if (args.width is None) != (args.height is None):
        parser.error("--width and --height must be used together")
    if args.width is not None and (args.width <= 0 or args.height <= 0):
        parser.error("--width and --height must be greater than 0")
    if args.preset and args.width is not None:
        parser.error("Use either --preset or --width/--height, not both")

    output_dir = ((args.output_dir or source.parent).resolve() / source.stem)
    output_dir.mkdir(parents=True, exist_ok=True)
    stem = _unique_stem(
        output_dir,
        _output_stem(args, source.stem),
        ("svg", "png") if args.format == "both" else (args.format,),
    )
    viewport = PRESETS[args.preset] if args.preset else None
    if args.width is not None:
        viewport = (args.width, args.height)
    try:
        if args.format in ("svg", "both"):
            _print_output(export_svg(source, output_dir / f"{stem}.svg"))
        if args.format in ("png", "both"):
            _print_output(export_png(source, output_dir / f"{stem}.png", args.scale, args.full_page, viewport))
    except (OSError, ValueError, RuntimeError) as error:
        print(str(error), file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
